<template>
  <section class="card-studio">
    <header><el-button v-if="!project" type="primary" @click="newProject()">新建制卡</el-button><el-button v-else @click="leaveProject">返回列表</el-button></header>
    <nav v-if="!project" class="studio-nav"><button v-for="item in panes" :key="item.key" :class="{active:pane===item.key}" @click="changePane(item.key)">{{ item.label }}</button></nav>
    <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">重试</el-button></el-alert>
    <div v-if="!project" v-loading="loading">
      <template v-if="pane==='projects'">
        <div v-if="sets.length" class="project-gallery">
          <article v-for="set in sets" :key="set._id" class="project-tile">
            <div class="project-pictures"><figure v-for="style in set.styles" :key="style.key"><el-image v-if="style.backgroundUrl" :src="style.backgroundUrl" fit="contain" :alt="tierLabel(style.key)"><template #error><span class="picture-missing">加载失败</span></template></el-image><span v-else class="picture-missing">待上传</span><figcaption>{{ tierLabel(style.key) }}</figcaption></figure></div>
            <div class="tile-heading"><h3>{{ set.title }}</h3><el-tag size="small" :type="set.status==='published'?'success':'info'">{{ set.status==='published'?(set.hasDraft?'有新草稿':'已发布'):'草稿' }}</el-tag></div>
            <p class="tile-scope">{{ kindLabel(set) }} · {{ scopeLabel(set.preload) }}</p>
            <div class="tile-actions"><el-button type="primary" @click="openProject(set._id)">{{ set.status==='published'&&!set.hasDraft?'编辑新版':'继续制作' }}</el-button><el-button v-if="canIssue(set)" @click="openIssue(set)">发放</el-button></div>
          </article>
        </div>
        <section v-if="legacyTiles.length" class="existing-materials" :class="{'after-projects':sets.length}">
          <h2>已有卡面</h2>
          <div class="project-gallery"><article v-for="tile in legacyTiles" :key="tile.id" class="project-tile">
            <div class="project-pictures"><figure v-for="style in tile.styles" :key="style.key"><el-image v-if="style.backgroundUrl" :src="style.backgroundUrl" fit="contain" :alt="tile.title+' '+tierLabel(style.key)"><template #error><span class="picture-missing">加载失败</span></template></el-image><span v-else class="picture-missing">待上传</span><figcaption>{{ tierLabel(style.key) }}</figcaption></figure></div>
            <div class="tile-heading"><h3>{{ tile.title }}</h3></div><p class="tile-scope">{{ kindLabel(tile) }} · {{ scopeLabel(tile.preload) }}</p>
            <p class="tile-next">{{ nextMaterialStep(tile.styles) }}</p><div class="tile-actions"><el-button type="primary" @click="newProject(tile)">继续制作</el-button></div>
          </article></div>
        </section>
        <el-empty v-if="!loading&&!sets.length&&!legacyTiles.length" description="还没有卡面，请新建制卡" :image-size="70" />
      </template>
      <template v-else-if="pane==='library'">
        <div class="style-library"><article v-for="set in published" :key="set._id"><div class="style-pictures"><figure v-for="style in set.styles" :key="style.key"><img v-if="style.backgroundUrl" :src="style.backgroundUrl" :alt="set.title"><figcaption>{{ tierLabel(style.key) }}</figcaption></figure></div><strong>{{ set.title }}</strong><p>{{ kindLabel(set) }} · {{ scopeLabel(set.preload) }}</p><el-button @click="openProject(set._id)">编辑新版</el-button><el-button v-if="canIssue(set)" type="primary" @click="openIssue(set)">发放</el-button></article></div>
        <el-empty v-if="!published.length" description="暂无已发布样式" :image-size="70" />
        <details v-if="legacyPublished.length" class="legacy-import"><summary>已发布旧样式（{{ legacyPublished.length }}）</summary><div class="style-library"><article v-for="item in legacyPublished" :key="item.id"><img class="old-style" :src="item.publishedBackgroundUrl || item.backgroundUrl" :alt="item.title"><strong>{{ item.title }}</strong><el-button @click="newProject(item)">整理新版</el-button></article></div></details>
      </template>
      <el-table v-else :data="issues" empty-text="暂无发放记录"><el-table-column prop="title" label="样式" /><el-table-column label="进度"><template #default="{row}">{{ row.cursor }} / {{ row.total }}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{ row.status==='complete'?'已完成':'待继续' }}</template></el-table-column><el-table-column label="展示设置"><template #default="{row}">{{ row.setDisplay?'发放后展示':'加入卡库' }}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status!=='complete'" link @click="resumeIssue(row)">继续发放</el-button></template></el-table-column></el-table>
    </div>
    <div v-else class="studio-project" v-loading="busy">
      <div class="project-title"><strong>{{ project.title }}</strong><span>{{ kindLabel(project) }} · {{ scopeLabel(project.preload) }}</span></div>
      <el-steps :active="step" finish-status="success" simple><el-step title="类型与范围" /><el-step title="上传素材" /><el-step title="调整排版" /><el-step title="预览发布" /></el-steps>
      <template v-if="step===1">
        <div class="material-tools"><label class="file-button">批量选择PNG<input type="file" accept="image/png,.png" multiple @change="chooseBatch"></label><el-checkbox v-if="project.kind==='progression'" v-model="sharedMask">三档共用遮罩</el-checkbox><label v-if="sharedMask" class="file-button">选择共用遮罩<input type="file" accept="image/png,.png" @change="chooseFile($event,'common','mask')"></label><span>{{ files.common?.mask?.name || '' }}</span></div>
        <p class="material-note">PNG 300×430，每张小于2MB。文件名可用“铜卡背景”“银卡背景”“金卡背景”“遮罩”。</p>
        <div class="material-grid"><section v-for="key in variantKeys" :key="key"><h3>{{ tierLabel(key) }}</h3><div class="material-preview"><img v-if="project.members[key].backgroundUrl" :src="project.members[key].backgroundUrl" alt="背景"><span v-else>待上传背景</span></div><label class="file-button">选择背景<input type="file" accept="image/png,.png" @change="chooseFile($event,key,'background')"></label><small>{{ files[key]?.background?.name || (project.members[key].backgroundFileId?'背景已保存':'') }}</small><label v-if="!sharedMask" class="file-button">选择遮罩<input type="file" accept="image/png,.png" @change="chooseFile($event,key,'mask')"></label><small v-if="!sharedMask">{{ files[key]?.mask?.name || (project.members[key].maskFileId?'遮罩已保存':'') }}</small></section></div>
        <p v-if="uploadProgress" role="status">{{ uploadProgress }}</p><div class="studio-actions"><el-button :loading="busy" @click="saveMaterials(false)">保存素材</el-button><el-button type="primary" :loading="busy" @click="saveMaterials(true)">下一步</el-button></div>
      </template>
      <template v-else-if="step===2">
        <div class="variant-tools"><el-radio-group :model-value="variant" @update:model-value="switchVariant"><el-radio-button v-for="key in variantKeys" :key="key" :value="key">{{ tierLabel(key) }}</el-radio-button></el-radio-group><el-checkbox v-if="project.kind==='progression'" v-model="sharedLayout">保存时同步三档排版</el-checkbox></div>
        <PlayerCardTemplateLibrary ref="editor" embedded :template-id="project.members[variant].id" />
        <div class="studio-actions"><el-button @click="backMaterials">上一步</el-button><el-button :loading="busy" @click="saveLayout">保存排版</el-button><el-button type="primary" :loading="busy" @click="prepareReview">预览{{ project.kind==='progression'?'整套':'卡片' }}</el-button></div>
      </template>
      <template v-else-if="step===3">
        <div class="review-styles"><figure v-for="card in previews" :key="card.key"><img :src="card.imageUrl" :alt="tierLabel(card.key)" @load="readyPreviews.add(card.key)" @error="readyPreviews.delete(card.key)"><figcaption>{{ tierLabel(card.key) }}</figcaption></figure></div>
        <p>{{ project.kind==='progression'?'确认后，铜银金三档将统一发布。':'确认后，此样式可按选定名单发放。' }}</p>
        <div class="studio-actions"><el-button @click="step=2">返回修改</el-button><el-button type="primary" :loading="busy" :disabled="readyPreviews.size!==variantKeys.length || !project.hasDraft" @click="publish">确认发布</el-button></div>
      </template>
      <template v-else-if="step===4"><el-alert title="样式已发布" type="success" :closable="false" /><div class="studio-actions"><el-button @click="project=null;changePane('library')">查看样式库</el-button><el-button v-if="canIssue(project)" type="primary" @click="openIssue(project)">选择名单发放</el-button></div></template>
    </div>
    <el-dialog v-model="createOpen" :title="usingExisting?'继续制作':'新建制卡'" width="min(620px, 94vw)" :close-on-click-modal="false">
      <p v-if="usingExisting" class="continue-note">已带入原有素材与排版，确认后继续编辑。</p>
      <el-form label-position="top"><el-form-item label="卡片类型"><el-radio-group v-model="creation.kind" @change="changeKind"><el-radio-button value="progression">金银铜升级套系</el-radio-button><el-radio-button value="honor">荣誉／特殊单卡</el-radio-button></el-radio-group></el-form-item><el-form-item label="名称"><el-input v-model.trim="creation.title" maxlength="24" /></el-form-item><el-form-item label="适用范围"><el-select v-model="creation.preload.type" @change="resetTargets"><el-option label="全平台" value="platform" /><el-option label="赛事／赛季" value="tournament" /><el-option v-if="creation.kind==='honor'" label="球队" value="team" /><el-option v-if="creation.kind==='honor'" label="个人" value="player" /></el-select></el-form-item><el-form-item v-if="creation.preload.type!=='platform'" label="选择对象"><el-select v-model="creation.preload.targetId" filterable remote :remote-method="searchTargets" :loading="targetsLoading" @visible-change="open=>open&&searchTargets('')"><el-option v-for="target in targets" :key="target.id" :value="target.id" :label="target.name" /><template #footer><el-button v-if="targetCursor" link @click="moreTargets">加载更多</el-button></template></el-select></el-form-item><el-form-item label="沿用旧素材"><el-select v-model="creation.importTemplateIds" multiple clearable><el-option v-for="item in legacy" :key="item.id" :value="item.id" :label="item.title" /></el-select></el-form-item></el-form>
      <template #footer><el-button @click="createOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="create">{{ usingExisting?'开始编辑':'创建项目' }}</el-button></template>
    </el-dialog>
    <el-dialog v-model="issueOpen" :title="issueProject?.title || '发放球员卡'" width="min(900px, 96vw)" :close-on-click-modal="false" :show-close="!issuing">
      <template v-if="!issueJob && !issueReview"><el-alert v-if="issueError" :title="issueError" type="error" :closable="false"><el-button link @click="openIssue(issueProject)">重试</el-button></el-alert><div class="issue-tools"><el-input v-model="recipientKeyword" placeholder="搜索球员或球队" clearable /><el-button @click="selectedIds=recipientRows.filter(x=>x.eligible).map(x=>x.id)">选择筛选结果</el-button><el-button @click="selectedIds=[]">清空</el-button></div><el-alert v-if="missingCount" :title="`${missingCount}条名单缺少球员档案，已列为待核查。`" type="warning" :closable="false" /><el-table :data="recipientPage" v-loading="recipientsLoading" row-key="id"><el-table-column label="选择" width="60"><template #default="{row}"><el-checkbox :model-value="selectedIds.includes(row.id)" :disabled="!row.eligible" @change="on=>selectRecipient(row.id,on)" /></template></el-table-column><el-table-column prop="name" label="球员" /><el-table-column prop="teamName" label="球队" /><el-table-column prop="reason" label="待处理" /></el-table><el-pagination v-if="recipientRows.length>30" v-model:current-page="recipientPageNumber" :page-size="30" :total="recipientRows.length" layout="prev, pager, next" /><p>已选择 {{ selectedIds.length }} 人</p><el-checkbox v-model="setDisplay">发放后设为展示卡</el-checkbox></template>
      <template v-else-if="!issueJob && issueReview"><p>已预览 {{ issueCards.length }} / {{ selectedIds.length }} 人</p><el-alert v-if="issueError" :title="issueError" type="error" :closable="false" /><div class="recipient-previews"><article v-for="card in issueCards" :key="card.playerId"><img v-if="card.cardUrl" :src="card.cardUrl" :alt="card.name"><span v-else>{{ card.cardError || '预览失败' }}</span><strong>{{ card.name }}</strong></article></div><el-button v-if="issueError || issueCards.some(x=>!x.cardUrl)" :loading="reviewingRecipients" @click="prepareIssueReview">重试预览</el-button></template><template v-else-if="issueJob"><p>已发放 {{ issueJob.completed || 0 }} / {{ issueJob.total }} 人</p><el-progress :percentage="Math.floor((issueJob.completed||0)*100/Math.max(1,issueJob.total))" /><el-alert v-if="issueError" :title="issueError" type="error" :closable="false" /><p v-if="issueJob.status==='complete'">发放完成</p></template>
      <template #footer><el-button :disabled="issuing" @click="issueOpen=false">关闭</el-button><el-button v-if="!issueJob && !issueReview" type="primary" :disabled="!selectedIds.length" :loading="reviewingRecipients" @click="prepareIssueReview">预览所选</el-button><template v-else-if="!issueJob"><el-button :disabled="reviewingRecipients" @click="issueReview=false">返回名单</el-button><el-button v-if="issueNext!==null" :loading="reviewingRecipients" @click="loadIssuePreview">加载更多</el-button><el-button type="primary" :loading="issuing" :disabled="reviewingRecipients || !!issueError || issueCards.length!==selectedIds.length || issueCards.some(x=>!x.cardUrl)" @click="beginIssue">确认发放</el-button></template><el-button v-else-if="issueJob.status!=='complete'" type="primary" :loading="issuing" @click="runIssue">继续发放</el-button></template>
    </el-dialog>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { playerCardTemplateRequest, uploadLargeFileViaCloud } from '@/utils/cloud'
import PlayerCardTemplateLibrary from './PlayerCardTemplateLibrary.vue'
import { legacyProjectTiles, nextMaterialStep } from '@/utils/playerCardProjectTiles'
const pane=ref('projects'),panes=[{key:'projects',label:'制作项目'},{key:'library',label:'已发布样式库'},{key:'issues',label:'发放记录'}]
const sets=ref([]),legacy=ref([]),issues=ref([]),loading=ref(false),busy=ref(false),error=ref(''),project=ref(null),step=ref(1),variant=ref('bronze'),editor=ref(null)
const files=reactive({}),sharedMask=ref(true),sharedLayout=ref(true),uploadProgress=ref(''),previews=ref([]),readyPreviews=reactive(new Set()),proof=ref('')
const createOpen=ref(false),creation=reactive({kind:'progression',title:'',preload:{type:'platform',targetId:''},importTemplateIds:[]}),targets=ref([]),targetsLoading=ref(false),targetCursor=ref(''),targetKeyword=ref('')
const issueRequestId=ref('')
const usingExisting=ref(false),legacyTiles=computed(()=>legacyProjectTiles(legacy.value))
const issueReview=ref(false),issueCards=ref([]),issueNext=ref(0),issuePreviewRevision=ref(0),reviewingRecipients=ref(false)
let issuePreviewEpoch=0
const issueOpen=ref(false),issueProject=ref(null),recipients=ref([]),selectedIds=ref([]),recipientKeyword=ref(''),recipientPageNumber=ref(1),recipientsLoading=ref(false),missingCount=ref(0),setDisplay=ref(true),issueJob=ref(null),issuing=ref(false),issueError=ref('')
watch(issueOpen,open=>{if(!open){issuePreviewEpoch++;reviewingRecipients.value=false}})
const variantKeys=computed(()=>project.value?.kind==='progression'?['bronze','silver','gold']:['single'])
const published=computed(()=>sets.value.filter(x=>x.status==='published')),legacyPublished=computed(()=>legacy.value.filter(x=>x.publishedVersion>0))
const recipientRows=computed(()=>recipients.value.filter(x=>[x.name,x.teamName].join(' ').includes(recipientKeyword.value))),recipientPage=computed(()=>recipientRows.value.slice((recipientPageNumber.value-1)*30,recipientPageNumber.value*30))
const tierLabel=key=>({bronze:'铜卡',silver:'银卡',gold:'金卡',single:'单卡'}[key]||key),kindLabel=row=>row.kind==='progression'?'金银铜套系':'荣誉／特殊卡',scopeLabel=scope=>({platform:'全平台',tournament:'赛事',team:'球队',player:'个人'}[scope?.type]||'未设置')+(scope?.targetName?' · '+scope.targetName:'')
const canIssue=row=>row.status==='published'&&!(row.kind==='progression'&&row.preload?.type==='platform')
async function api(workflowAction,data={}){const r=await playerCardTemplateRequest('savePlayerCardTemplate',{workflowAction,...data});if(!r?.success)throw new Error(r?.error||'制卡操作失败，请重试');return r}
async function load(){loading.value=true;error.value='';try{const r=await api('list');sets.value=r.sets;legacy.value=r.legacy}catch(e){error.value=e.message}finally{loading.value=false}}
async function changePane(value){pane.value=value;if(value==='issues'){loading.value=true;try{issues.value=(await api('issues')).issues}catch(e){error.value=e.message}finally{loading.value=false}}else await load()}
function newProject(old){usingExisting.value=!!old;Object.assign(creation,{kind:old?.kind||(old&&['team','player'].includes(old.preload?.type)?'honor':'progression'),title:old?.title||'',preload:old?{...old.preload}:{type:'platform',targetId:''},importTemplateIds:old?(old.importTemplateIds||[old.id]):[]});targets.value=old?.preload?.targetId?[{id:old.preload.targetId,name:old.preload.targetName||old.preload.targetId}]:[];createOpen.value=true}
function changeKind(){if(creation.kind==='progression'&&!['platform','tournament'].includes(creation.preload.type))creation.preload={type:'platform',targetId:''}}
function resetTargets(){creation.preload.targetId='';targets.value=[];targetCursor.value=''}
async function searchTargets(keyword='',more=false){if(creation.preload.type==='platform')return;targetsLoading.value=true;targetKeyword.value=keyword;try{const r=await playerCardTemplateRequest('listPlayerCardPreloadTargets',{type:creation.preload.type,keyword,cursor:more?targetCursor.value:''});if(!r.success)throw new Error(r.error);targets.value=more?[...targets.value,...r.targets]:r.targets;targetCursor.value=r.nextCursor||''}catch(e){ElMessage.error(e.message)}finally{targetsLoading.value=false}}
function moreTargets(){return searchTargets(targetKeyword.value,true)}
async function create(){busy.value=true;try{const r=await api('create',JSON.parse(JSON.stringify(creation)));project.value=r.set;variant.value=project.value.kind==='progression'?'bronze':'single';step.value=1;createOpen.value=false;for(const key of Object.keys(files))delete files[key]}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function openProject(id){busy.value=true;try{project.value=(await api('get',{setId:id})).set;variant.value=project.value.kind==='progression'?'bronze':'single';step.value=Object.values(project.value.members).every(x=>x.backgroundFileId&&x.maskFileId)?2:1;for(const key of Object.keys(files))delete files[key]}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function reloadProject(){project.value=(await api('get',{setId:project.value._id})).set}
async function validateFile(file){if(!file||file.size>2*1024*1024||!(/\.png$/i.test(file.name)))throw new Error('请选择小于2MB的PNG');const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);if(bytes[0]!==137||bytes[1]!==80||bytes[2]!==78||bytes[3]!==71)throw new Error('文件不是PNG');if(buffer.byteLength<24)throw new Error('PNG文件不完整');const view=new DataView(buffer);if(view.getUint32(16)!==300||view.getUint32(20)!==430)throw new Error('图片尺寸须为300×430');return file}
async function chooseFile(event,key,layer){try{const file=await validateFile(event.target.files?.[0]);(files[key]||={})[layer]=file}catch(e){ElMessage.error(e.message)}event.target.value=''}
async function chooseBatch(event){try{for(const file of event.target.files||[]){await validateFile(file);const mask=/遮罩|mask/i.test(file.name),key=project.value.kind==='honor'?'single':/铜|bronze/i.test(file.name)?'bronze':/银|silver/i.test(file.name)?'silver':/金|gold/i.test(file.name)?'gold':mask&&sharedMask.value?'common':'';if(!key)throw new Error('无法识别 '+file.name+'，请使用单项选择');(files[key]||={})[mask?'mask':'background']=file}}catch(e){ElMessage.error(e.message)}event.target.value=''}
async function upload(file,layer){const token=crypto.randomUUID();const r=await uploadLargeFileViaCloud(`player-card-template-uploads/${token}/${layer}/asset.png`,file,{chunkSize:16*1024,fallbackChunkSize:8*1024,onProgress:(done,total)=>{uploadProgress.value=`${file.name}：${done}/${total}`}});return r.fileId}
async function saveMaterials(next){busy.value=true;try{const common=sharedMask.value&&files.common?.mask?await upload(files.common.mask,'mask'):'';for(const key of variantKeys.value){const chosen=files[key]||{},member=project.value.members[key];if(!chosen.background&&!chosen.mask&&!common)continue;const input={key,revision:member.revision};if(chosen.background)input.backgroundFileId=await upload(chosen.background,'background');if(common)input.maskFileId=common;else if(chosen.mask)input.maskFileId=await upload(chosen.mask,'mask');const r=await api('materials',{setId:project.value._id,variants:[input]});project.value=r.set;delete files[key]}delete files.common;uploadProgress.value='';if(next){if(!Object.values(project.value.members).every(x=>x.backgroundFileId&&x.maskFileId))throw new Error('请补齐各档背景和遮罩');step.value=2}ElMessage.success('素材已保存')}catch(e){ElMessage.error(e.message);await reloadProject().catch(()=>{})}finally{busy.value=false}}
async function saveLayout(){busy.value=true;try{if(editor.value?.isDirty()){const ok=await editor.value.saveChanges();if(!ok)return false}if(project.value.kind==='progression'&&sharedLayout.value){const form=editor.value.formData();await api('copyLayout',{setId:project.value._id,sourceKey:variant.value,revision:form.revision})}await reloadProject();return true}catch(e){ElMessage.error(e.message);return false}finally{busy.value=false}}
async function switchVariant(key){if(key===variant.value)return;if(editor.value?.isDirty()&&!await saveLayout())return;variant.value=key}
async function backMaterials(){if(editor.value?.isDirty()&&!await saveLayout())return;step.value=1}
async function prepareReview(){if(!await saveLayout())return;busy.value=true;try{const r=await api('review',{setId:project.value._id});previews.value=r.cards;proof.value=r.proof;readyPreviews.clear();step.value=3}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function publish(){busy.value=true;try{const r=await api('publish',{setId:project.value._id,proof:proof.value});project.value=r.set;step.value=4;ElMessage.success('样式已发布');await load()}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function leaveProject(){if(editor.value?.isDirty()){try{await ElMessageBox.confirm('排版尚未保存，先保存再离开？','保存草稿',{confirmButtonText:'保存',cancelButtonText:'继续编辑'});if(!await saveLayout())return}catch{return}}project.value=null;await load()}
async function openIssue(set){issueProject.value=set;issueReview.value=false;issueCards.value=[];reviewingRecipients.value=false;issuePreviewEpoch++;issueRequestId.value=crypto.randomUUID();issueOpen.value=true;issueJob.value=null;issueError.value='';selectedIds.value=[];recipients.value=[];recipientKeyword.value='';recipientPageNumber.value=1;setDisplay.value=true;recipientsLoading.value=true;try{const r=await api('candidates',{setId:set._id});recipients.value=r.players;missingCount.value=r.missingCount||0}catch(e){issueError.value=e.message;ElMessage.error(e.message)}finally{recipientsLoading.value=false}}
function selectRecipient(id,on){selectedIds.value=on?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(x=>x!==id)}
async function beginIssue(){issuing.value=true;try{issueJob.value=await api('beginIssue',{requestId:issueRequestId.value,previewRevision:issuePreviewRevision.value,setId:issueProject.value._id,playerIds:selectedIds.value,setDisplay:setDisplay.value});await runIssue()}catch(e){issueError.value=e.message;ElMessage.error(e.message)}finally{issuing.value=false}}
async function runIssue(){issuing.value=true;issueError.value='';try{while(issueJob.value.status!=='complete')issueJob.value=await api('continueIssue',{jobId:issueJob.value.jobId});ElMessage.success('发放完成')}catch(e){issueError.value=e.message}finally{issuing.value=false}}
function resumeIssue(row){issueProject.value={title:row.title};issueJob.value={jobId:row._id,total:row.total,completed:row.cursor,status:row.status};issueError.value='';issueOpen.value=true}
async function prepareIssueReview(){issueReview.value=true;issueCards.value=[];issueNext.value=0;issueError.value='';issuePreviewEpoch++;await loadIssuePreview()}
async function loadIssuePreview(){const epoch=issuePreviewEpoch;if(reviewingRecipients.value||issueNext.value===null)return;reviewingRecipients.value=true;issueError.value='';try{const r=await api('issuePreviews',{setId:issueProject.value._id,playerIds:selectedIds.value,offset:issueNext.value});if(epoch!==issuePreviewEpoch)return;if(issueCards.value.length&&issuePreviewRevision.value!==r.revision)throw new Error('样式已更新，请重新预览');issueCards.value.push(...r.cards);issueNext.value=r.nextOffset;issuePreviewRevision.value=r.revision}catch(e){if(epoch===issuePreviewEpoch)issueError.value=e.message}finally{if(epoch===issuePreviewEpoch)reviewingRecipients.value=false}}
onMounted(load)
</script>

